FlowEdgeSchema includes `type: 'default' | 'fault'`, but on node failure the engine throws and aborts the whole flow. This prevents any fault path execution. Consider routing errors to outgoing `fault` edges (and only following `default` edges on success) to match the protocol.
```suggestion
        let nodeSucceeded = true;

        // Find executor
        const executor = this.nodeExecutors.get(node.type);
        if (!executor) {
            // start node without executor is fine — just skip
            if (node.type !== 'start') {
                // Treat missing executor as node failure and allow fault edges to handle it
                nodeSucceeded = false;
            }
        } else {
            // Execute node
            try {
                const result = await executor.execute(node, variables, context);
                nodeSucceeded = !!result.success;

                // On success, write back output variables
                if (nodeSucceeded && result.output) {
                    for (const [key, value] of Object.entries(result.output)) {
                        variables.set(`${node.id}.${key}`, value);
                    }
                }
            } catch {
                // Runtime executor error — treat as node failure and route via fault edges
                nodeSucceeded = false;
            }
        }

        // Find next nodes (filter by edge type and conditions)
        const desiredEdgeType = nodeSucceeded ? 'default' : 'fault';
        const outEdges = flow.edges.filter(
            e => e.source === node.id && (e as any).type === desiredEdgeType,
        );
