            const originalExecute = this.engine.execute.bind(this.engine);
            this.engine.execute = (async (...args: unknown[]) => {
                const flowName = typeof args[0] === 'string' ? args[0] : 'unknown';
                ctx.logger.debug(`[Automation] Before execute: ${flowName}`);
                return originalExecute(...(args as any[]));
            }) as typeof this.engine.execute;
